preConditionHook:
// EL: atrValue = WFSafe_AvgTrueRange(atrLookback); the condition reads
// atrValue for this bar and atrValue[1] for the previous one.
// atrPrev is taken BEFORE the accumulator is advanced, so it holds exactly what
// the EL variable's own history would return: 0 for bars before the strategy's
// first evaluated one (both start at 0.0), the prior bar's value after -- the
// zero-padded variable warm-up AtrRising documents. Only lag 1 is needed, so a
// single carried value replaces the ring buffer.
atrPrev = atrValue;
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: seeded with a full sum on the study's first calculated bar, and updated
// thereafter as S += TrueRange - TrueRange[Length] in TWO statements (EL evaluates
// S[1] + in - out left to right; folding it to S += in - out rounds
// differently). atrLength != atrLookback re-seeds, as the WFSafe_ wrappers do
// when a walkforward re-optimization changes the length. See AtrProfitTarget.
if (atrLength != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrValue = atrSum / (int)atrLookback;
// The opposite-direction test is written as two explicit branches rather than
// as a not-equal between two booleans: a doji (close = open) has no direction
// and satisfies neither branch, which is what 'closed in opposite directions'
// means, and it keeps the test to ordinary EL relationals -- the same reading
// OppositeLargeBarsInWindow uses.
